  "烟雾材质的近镜头淡出要用": "The close-up of the smoke material needs to be used.",
  "uniform sampler2D map; uniform sampler2D lut; uniform float lutMin, lutMix, emissiveMult, lutVariant, nLuts, errorFix; uniform bool rot90, useLut, useAlpha, texColor, particleColor; varying vec2 vUv; varying vec4 vCol; void main() { vec2 uv = rot90 ? vec2(1.0 - vUv.y, vUv.x) : vUv; vec4 t = texture2D(map, uv); float op = useAlpha ? t.a : t.g; vec3 e; if (texColor) e = t.rgb * emissiveMult; else { vec3 c; if (useLut) { float k = mix(lutMin, lutMix, t.g); vec2 luv = mix(vec2(k, (k + lutVariant) / nLuts), vec2((lutVariant + 0.5) / nLuts), errorFix); c = texture2D(lut, luv).rgb; } else c = vec3(t.g); e = c * emissiveMult; if (particleColor) e *= vCol.rgb; } float a = clamp(op * vCol.a, 0.0, 1.0); gl_FragColor = vec4(max(e, vec3(0.0)) * a, a); // 线性、预乘 }": "=a uniform sampler2D cap; uniform sampler2D let; uniform nitmin, utmix, utvarant, nitvarant, errorFix; uniform rot90, useLut, usealpha, textColor; vycllor; verying vec2 vUv; varyc4 vCol; voi (vg) ; voi g(e ) & ; utl & ; utl ; ut & & ; tl & & ; tlveve & & ; veve & t & & ; tv & & & & & & ; tv & & & & & & & & & & & & & ; & & & & & & & & & & &",
  "线性": "Linear",
  "预乘": "Pre-expanded",
  "uniform sampler2D mapE; uniform sampler2D mapO; uniform float gameTime; uniform vec4 pE; // rot, rate, -, - uniform vec4 pE2; // scale.xy, offset.xy uniform vec4 pO; // rot, rate, scrollU, scrollV uniform vec4 pO2; // scale.xy, offset.xy uniform vec4 pO1; // rot, rate, scrollU, scrollV uniform vec4 pO12;// scale.xy, offset.xy uniform vec3 pFade; // 1/半径(每厘米), 1/(1−硬度), 1/软粒子距离(每厘米) varying vec2 vUv; varying vec4 vCol; varying float vViewZ; vec2 rot(vec2 q, float turns) { float a = turns * 6.28, s = sin(a), c = cos(a); return vec2(c * q.x - s * q.y, s * q.x + c * q.y); } void main() { vec2 p = vUv * 4.0 - 2.0; vec2 q = vec2(fract(atan(p.y, p.x) * 0.159155), length(p)) - 0.5; vec2 gx = dFdx(vUv), gy = dFdy(vUv); float t = gameTime; vec2 uvE = (rot(q, pE.y * t + pE.x) + 0.5) * pE2.xy + pE2.zw; float e = textureGrad(mapE, uvE, gx, gy).r; vec2 uvA = (rot(q, pO.y * t + pO.x) + 0.5) * pO2.xy + pO2.zw; uvA = vec2(uvA.x + pO.z * t, clamp(uvA.y + pO.w * t, 0.01, 0.99)); float a = textureGrad(mapO, uvA, gx, gy).r * vCol.a; vec2 uvB = (rot(q, pO1.y * t + pO1.x) + 0.5) * pO12.xy + pO12.zw; uvB = vec2(uvB.x + pO1.z * t, clamp(uvB.y + pO1.w * t, 0.01, 0.99)); float b = textureGrad(mapO, uvB, gx, gy).r; float pix = vViewZ * 100.0; // 厘米 float camFade = 1.0 - clamp((1.0 - abs(pix) * pFade.x) * pFade.y, 0.0, 1.0); float op = clamp(camFade * a * b, 0.0, 1.0); gl_FragColor = vec4(e * vCol.rgb * op, op); }": "= > & & & & & & / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / /",
