  "uniform sampler2D map; uniform bool alphaFromLum, softCircle; varying vec2 vUv; varying vec4 vCol; void main() { vec4 t = texture2D(map, vUv); float g = clamp(dot(t.rgb, vec3(0.299, 0.587, 0.114)), 0.0, 1.0); float op = alphaFromLum ? g : t.a; // 满 alpha 的平铺云纹（程序烟团）原材质靠渐变贴图收成一团；按圆形柔边近似 if (softCircle) op *= smoothstep(1.0, 0.25, length(vUv - 0.5) * 2.0); float a = clamp(op * vCol.a, 0.0, 1.0); // 只取明暗：程序烟用的噪声贴图三个通道是互不相关的噪声，直接当颜色会出现绿色等杂色；颜色交给粒子色 gl_FragColor = vec4(vec3(g) * vCol.rgb * a, a); }": "uniform sampler2D Map; uniform bool alphaFrom, softCircle; valying vec2 vUv; varing vec4 & Col; {vec4 = texture2D (map, vUv); float g = clapt (t.rgb, vec3(0.29Circle) * smoothep (1.0, lngt = alphaFromLum? g: t. = tvg = & ; = = * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * } } } } } } } }",
