  "uniform vec3 alSeam; uniform float alScale; float alHash1( vec2 cell ) { return fract( sin( dot( cell, vec2( 127.1, 311.7 ) ) ) * 43758.5453123 ); } vec2 alHash2( vec2 cell ) { return fract( sin( vec2( dot( cell, vec2( 127.1, 311.7 ) ), dot( cell, vec2( 269.5, 183.3 ) ) ) ) * 43758.5453123 ); } // 按几何法线挑投影面：地面/天花走 XZ，朝 ±X 的墙走 ZY，朝 ±Z 的墙走 XY。 // 法线用世界坐标的屏幕导数现算，不读几何体的 normal/uv 属性——斜坡两样都没有。 vec2 alProject( vec3 wp ) { vec3 n = abs( cross( dFdx( wp ), dFdy( wp ) ) ); if ( n.y >= n.x && n.y >= n.z ) return wp.xz; if ( n.x >= n.z ) return wp.zy; return wp.xy; } // 一个像素在世界里的边长（米）。反走样宽度取它，而**不是** fwidth(花纹值)： // 花纹值在砖缝处不连续，fwidth 会在那里炸出一圈亮边。 float alPixelSize( vec2 p ) { return max( length( dFdx( p ) ), length( dFdy( p ) ) ) + 1e-6; }": "* * ** ** ** ** ** ** ± ± ± ± Z ± ± ± ± ± ± ± ± ± ± ± ± ** ± ** ± ± ** ** ** ** ** ** ** & ± & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & / & & & & & & & & & / & & & / & & / / & & & & & & / & & & & & & & & & & / & & & & & &",
