  "vec3 alSurfacePattern( vec3 base, vec2 p, float px ) { float stone = alScale; float mortar = stone * 0.10; // 缝宽随尺度等比缩放，不是绝对值 vec2 cell = p / stone; vec2 origin = floor( cell ); vec2 f = fract( cell ); float best = 8.0; float second = 8.0; vec2 bestId = origin; for ( int y = -1; y <= 1; y ++ ) { for ( int x = -1; x <= 1; x ++ ) { vec2 g = vec2( float( x ), float( y ) ); float d = length( g + alHash2( origin + g ) - f ); if ( d < best ) { second = best; best = d; bestId = origin + g; } else if ( d < second ) { second = d; } } } float edge = ( second - best ) * stone; float face = smoothstep( mortar - px, mortar + px, edge ); float shade = 0.86 + 0.28 * alHash1( bestId ); vec3 patterned = mix( alSeam, base * shade, face ); // 0.18 ≈ 灰浆在铺装里占的面积比（石块比方格缝宽，故大于方格的 0.11）。 vec3 far = mix( base, alSeam, 0.18 ); return mix( far, patterned, 1.0 - smoothstep( stone * 0.12, stone * 0.5, px ) ); }": "& & & & & & & & & & & & & & / / wide scale & band & not absolute & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & & ( & & & & & & & & ( & ( & & & & &",
