  "uniform float uTime; uniform float uTele; varying vec3 vN; varying vec3 vV; varying vec3 vP; void main() { // 双面：在烟里看到的是内壁，法线翻过来朝向自己 vec3 N = normalize(vN) * (gl_FrontFacing ? 1.0 : -1.0); float f = pow(1.0 - abs(dot(N, normalize(vV))), 2.2); float a = atan(vP.z, vP.x); float s1 = smoothstep(0.8, 1.0, sin(a * 5.0 + vP.y * 6.0 + uTime * 1.4) * 0.5 + 0.5); float s2 = smoothstep(0.88, 1.0, sin(a * 9.0 - vP.y * 10.0 - uTime * 2.1) * 0.5 + 0.5); vec3 body = vec3(0.66, 0.76, 0.86); vec3 rim = vec3(0.92, 0.97, 1.0); float lit = 0.8 + 0.2 * max(dot(N, normalize(vec3(0.3, 0.8, 0.5))), 0.0); vec3 col = mix(body, rim, clamp(f * 1.25 + s1 * 0.35 + s2 * 0.25, 0.0, 1.0)) * lit + uTele * f * 0.5; gl_FragColor = vec4(col, 1.0); }": "+ , + , + , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , , ,",
