  "precision highp float; varying vec2 vUv; uniform vec2 uSrc; uniform float uAspect, uTime, uSource, uWash, uWashSize, uGain, uSize, uInFront, uLuma; uniform sampler2D uGlow; uniform vec3 uColorB, uColorC, uBg; uniform vec4 uA, uA2, uE; /* * ---- 放射光刺 ---- * 游戏把 T_Noise_Snow_Grayscale 按极坐标采样：U = 角度 x TextureAUtile(4)、 * V = 半径 x TextureAVtile(0.02)，所以是\"角向高频 + 径向几乎不变\"。 * 光刺根数由那张噪声图的像素密度决定，而它 BC 压缩解不开 —— 根数是对着游戏截图配的。 * 角向噪声必须是周期的（下标对 freq 取模），否则 0/360 度接缝会出现一条突兀的直线。 */ float angHash(float i, float seed) { return fract(sin((i + seed) * 12.9898) * 43758.5453); } float angNoise(float a01, float freq, float seed) { float x = a01 * freq; float i = floor(x), f = fract(x); f = f * f * (3.0 - 2.0 * f); return mix(angHash(mod(i, freq), seed), angHash(mod(i + 1.0, freq), seed), f); } /* ridge 把平缓噪声翻成尖脊，脊线就是一根刺；两个指数叠出「细亮芯 + 宽软裙」。 pow 的底数必须 clamp 到 >= 0：ridge 会有 -1e-8 级的浮点误差，负底数在 GLSL 未定义。 */ float beam(float a01, float freq, float seed, float corePow, float skirtPow, float w) { float n = clamp(1.0 - abs(angNoise(a01, freq, seed) * 2.0 - 1.0), 0.0, 1.0); return (pow(n, corePow) * 0.72 + pow(n, skirtPow) * 0.30) * w; } void main() { vec2 d = vUv - uSrc; d.x *= uAspect; float r = length(d); float a01 = atan(d.y, d.x) * 0.15915494 + 0.5; float flow = r * uA.y * 50.0 + uTime * uA.z; float rays = beam(a01 + flow * 0.004, 29.0, 0.0, uA2.x * 3.6, uA2.x * 1.0, 0.85) + beam(a01 + flow * 0.007, 61.0, 7.3, uA2.x * 4.8, uA2.x * 1.4, 0.65) + beam(a01 + flow * 0.011, 127.0, 19.1, uA2.x * 6.4, uA2.x * 2.0, 0.45); rays *= 0.88 + 0.12 * sin(flow * 3.0); rays *= uA.w; float lobes = pow(clamp(angNoise(a01 + uTime * 0.02, max(uE.x, 1.0) * 6.0, 3.1), 0.0, 1.0), max(uE.w, 0.001)) * (uE.z * 0.25); /* 一路射到画面边缘（四角还剩三成半），中心 0.05 以内反而压掉 —— 不压的话所有刺会在圆心汇成一个脏点，而游戏那里是干净的白球。 */ float radial = clamp(r / 0.05, 0.0, 1.0) * (0.35 + 0.65 * exp(-r * 0.9)); vec2 gu = d / max(uA2.y * uSize * 0.9, 1e-4) * 0.5 + 0.5; float halo = 0.0; if (gu.x > 0.0 && gu.x < 1.0 && gu.y > 0.0 && gu.y < 1.0) halo = texture2D(uGlow, gu).r; /* 贴图采样框的边界会切出一圈硬边（GlowA01 的边缘不是纯 0），补一层径向羽化。 */ halo *= 1.0 - smoothstep(0.34, 0.50, length(gu - vec2(0.5))); float core = 1.0 / (1.0 + r * r * 900.0); /* 背景层不乘 uInFront：源点转到身后时屏幕仍被糊住一层，游戏里确实如此， 只是那一团刺看不见了。 */ float bg = pow(clamp(1.0 - r / max(uBg.y * uWashSize, 1e-3), 0.0, 1.0), uBg.x); /* 爆点（halo + core）不乘 uSource —— 射线先消失，那颗白点要亮到最后。 */ float e = (rays * radial * (0.75 + lobes) * 1.35 * uSource + halo * 1.3 + core * 11.0) * uInFront; vec3 col = vec3(0.55) + mix(uColorB * 0.60, uColorC * 1.00, bg); /* 饱和要用软的：min(e, 3.0) 会在 e=3 那条等值线上留一道硬接缝，表现是核心外面一圈 细亮环（一度误判成光晕贴图自带的）。色相插值同理用 smoothstep。 */ vec3 hot = mix(uColorB, uColorC, smoothstep(0.0, 2.0, e)); col += hot * (3.0 * e / (3.0 + e)); col *= uGain; col = col / (1.0 + col) * 1.6; /* 无障碍：uLuma 只动亮度，**绝不动覆盖度**。alpha 恒等于 uWash —— 调低强度后屏幕 照样全糊，看不见的东西一样看不见，训练难度一个字节都没变。让它去改 alpha， 低强度就成了\"能透过闪光看见靶子\"，那是作弊不是无障碍。 */ col = mix(vec3(0.34), col, clamp(uLuma, 0.0, 1.0)); gl_FragColor = vec4(col, clamp(uWash, 0.0, 1.0)); }": "* u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u u * * * * u * * * u u u * * * * * *",
