  "bản đồ lấy mẫu thống nhất2D; bộ lấy mẫu thống nhất2D mapO; trò chơi nổi thống nhấtThời gian; vec4 pE đồng nhất; // thối, tỷ lệ, -, - thống nhất vec4 pE2; //scale.xy, offset.xy thống nhất vec4 pO; // thối, tốc độ, cuộnU, cuộnV thống nhất vec4 pO2; //scale.xy, offset.xy thống nhất vec4 pO1; // rot, rate, ScrollU, ScrollV thống nhất vec4 pO12;//scale.xy, offset.xy thống nhất vec3 pFade; // 1/bán kính (trên centimet), 1/(1−độ cứng), 1/khoảng cách hạt mềm (trên centimet) thay đổi vec2 vUv; thay đổi vec4 vCol; vViewZ nổi khác nhau; vec2 rot(vec2 q, float lượt) { float a = lượt * 6.28, s = sin(a), c = cos(a); return vec2(c * q.x - s * q.y, s * q.x + c * q.y); } void main() { vec2 p = vUv * 4.0 - 2.0; vec2 q = vec2(fract(atan(p.y, p.x) * 0,159155), length(p)) - 0,5; vec2 gx = dFdx(vUv), gy = dFdy(vUv); float t = gameTime; vec2 uvE = (rot(q, pE.y * t + pE.x) + 0,5) * pE2.xy + pE2.zw; float e = textGrad(mapE, uvE, gx, gy).r; vec2 uvA = (rot(q, pO.y * t + pO.x) + 0,5) * pO2.xy + pO2.zw; uvA = vec2(uvA.x + pO.z * t, kẹp(uvA.y + pO.w * t, 0,01, 0,99)); float a = textGrad(mapO, uvA, gx, gy).r * vCol.a; vec2 uvB = (rot(q, pO1.y * t + pO1.x) + 0,5) * pO12.xy + pO12.zw; uvB = vec2(uvB.x + pO1.z * t, kẹp(uvB.y + pO1.w * t, 0,01, 0,99)); float b = textGrad(mapO, uvB, gx, gy).r; float pix = vViewZ * 100.0; // cm float camFade = 1.0 - kẹp((1.0 - abs(pix) * pFade.x) * pFade.y, 0.0, 1.0); float op = kẹp (camFade * a * b, 0,0, 1,0); gl_FragColor = vec4(e * vCol.rgb * op, op); }": "= > & & & & & & / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / /",
