  "bản đồ lấy mẫu thống nhất2D; bộ lấy mẫu thống nhất2D mapO; trò chơi nổi thống nhấtThời gian; vec4 pE đồng nhất; // thối, tốc độ, cuộnU, cuộnV thống nhất vec4 pE2; //scale.xy, offset.xy thống nhất vec4 pO; // thối, tốc độ, cuộnU, cuộnV thống nhất vec4 pO2; //scale.xy, offset.xy thống nhất vec3 pFade; // 1/bán kính (trên centimet), 1/(1−độ cứng), 1/khoảng cách hạt mềm (trên centimet) vec3 pK đồng đều; // AlphaPower, Alpha_ColorMult, EmissivePower đồng phục vec3 emisCol; thay đổi vec2 vUv; thay đổi vec4 vCol; vViewZ nổi khác nhau; vec2 rot(vec2 q, float lượt) { float a = lượt * 6.28, s = sin(a), c = cos(a); return vec2(c * q.x - s * q.y, s * q.x + c * q.y); } float pw(float x, float k) { return x <= 0,0 ? 0,0 : pow(x, k); } void main() { float t = gameTime; vec2 d = vUv - 0,5; vec2 uvA = (rot(d, pO.y * t + pO.x) + 0,5) * pO2.xy + pO2.zw + pO.zw * t; float a = pw(texture2D(mapO, uvA).r, pK.x); vec2 uvE = (rot(d, pE.y * t + pE.x) + 0,5) * pE2.xy + pE2.zw + pE.zw * t; vec4 e = kết cấu2D(mapE, uvE); float pix = vViewZ * 100.0; // cm float camFade = 1.0 - kẹp((1.0 - abs(pix) * pFade.x) * pFade.y, 0.0, 1.0); float op = kẹp(a * e.a * pK.y * vCol.a * camFade, 0,0, 1,0); vec3 c = vec3(pw(e.r, pK.z), pw(ví dụ: pK.z), pw(e.b, pK.z)) * emisCol * vCol.rgb; gl_FragColor = vec4(max(c, vec3(0.0)) * op, op); }": "= u & & & & & & & / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / /",
  "bản đồ sampler2D thống nhất; trò chơi nổi thống nhấtThời gian; vec4 pA đồng nhất; // Pan_X, Pan_Y, Cân_X, Cân_Y thống nhất vec4 pB; // Distortion_Strength, 1/max(Distort_Radus,1e-5), Distortion_Speed, Edge_Distortion thống nhất vec4 pC; // TempRadius, Temp, Tex_Power, Đồng phục xói mòn vec4 pD; // 1/max(Edge_Radius,1e-5), 1/max(1−Edge_Hardness,1e-5), 1/max(DepthFade_Dist,1e-5)(per centimet), ánh sáng sai đồng nhất vec3 tint; // Color.rgb × Color.a thay đổi vec2 vUv; thay đổi vec4 vCol; thay đổi vec4 vDyn; // BlackBody của UE (không bao gồm mục cường độ) vec3 blackbody(float T) { float T2 = T * T; float u = (0,860117757 + 1,54118254e-4 * T + 1,28641212e-7 * T2) / (1,0 + 8,42420235e-4 * T + 7,08145163e-7 * T2); float v = (0,317398726 + 4,22806245e-5 * T + 4,20481691e-8 * T2) / (1,0 - 2,89741816e-5 * T + 1,61456053e-7 * T2); float den = 2,0 * u - 8,0 * v + 4,0; float x = 3,0 * u/den, y = 2,0 * v/den; vec3 XYZ), dot(vec3(-0.9692660, 1.8760108, 0.0415560), XYZ), dot(vec3(0.0556434, -0.2040259, 1.0572252), XYZ)); } void main() { vec2 uv = vUv; float t = gameTime; float dist = chiều dài (uv - 0,5); float m = kẹp(1.0 - dist * pB.y, 0.0, 1.0); float s = vDyn.w * 0,4 + 0,5, sp = vDyn.w * 0,6 + 0,8, k = vDyn.w * 0,08 + 0,18; vec2 panYX = t * vec2(pA.y, pA.x), panXY = t * pA.xy; vec2 uvYX = vec2(uv.y * pA.w, uv.x * pA.z), uvXY = vec2(uv.x * pA.z, uv.y * pA.w); tốc độ nổi = t * pB.z * sp; float lo = -0,2 * pB.x/s, hi = 0,2 * pB.x/s; vec2 n1 = kết cấu2D(map, uvYX * s + panYX).xy; float baseA = mix(m, n1.x, 0,2) + tốc độ * 0,25; float w = kẹp((sin((baseA + 0,25) * 6,283185) + 0,75) * 0,75, 0,0, 1,0); vec2 P = mix(uvYX + 0,5, n1 + 0,5, mix(lo, hi, fract(baseA + 0,5))); float sA = text2D(map, P * s + panYX).b; vec2 n2 = text2D(map, uvXY * s + panXY).xy; float baseB = mix(m, n2.x, 0,2) + * 0,25; vec2 Q = uvXY + mix(lo, hi, fract(baseB)) * (n2 - uvXY); float sB = text2D(map, Q * s + panXY).b; tiếng ồn nổi = mix(sB, sA, w); if (nhiễu <= 0,0) { gl_FragColor = vec4(0,0); trở lại; } vec3 col = vCol.rgb * tint * pow(nhiễu, pC.z); float rơi = max(1.0 - dist / max(vDyn.z * pC.x, 1e-5), 0,0); float T = (1.0 - tiếng ồn) * rơi * rơi * vDyn.y * pC.y; col += vật đen(T) * pow(T * 0,0004, 4,0); col *= pD.w; vec2 uv2 = uv + (k * pB.w) * (vec2(nhiễu) - uv); cạnh nổi = kẹp ((1,0 - chiều dài (uv2 - 0,5) * pD.x) * pD.y, 0,0, 1,0); float op = kẹp(cạnh * pow(nhiễu, vDyn.x * pC.w) * vCol.a, 0,0, 1,0); gl_FragColor = vec4(max(col, vec3(0.0)) * op, op); }": "* = u & / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / / /",
